  "Descall wins for squads that want DMs, groups, WebRTC voice/video, and screen share without Nitro. It is not trying to replace every public Discord server.": "Descall выигрывает для команд, которым нужны ЛС, группы, голос и видео на WebRTC и демонстрация экрана без Nitro. Он не пытается заменить каждый публичный сервер Discord.",
