  "Free core messaging, cosmetics optional via DesCoin": "Основные сообщения бесплатно, косметика за DesCoin по желанию",
  "Free core, cosmetics optional": "Основное бесплатно, косметика по желанию",
  "Free core, no Nitro to queue with friends": "Основное бесплатно, Nitro не нужен, чтобы играть с друзьями",
  "Free core, optional cosmetics": "Основное бесплатно, косметика по желанию",
  "Free spins": "Бесплатные вращения",
  "Free to use": "Бесплатно",
  "Free voice chat for gamers": "Бесплатный голосовой чат для геймеров",
  "Freeze Chat": "Заморозить чат",
  "Frequently asked questions": "Частые вопросы",
  "Frequently asked questions about Descall, accounts, desktop download, calls, screen share, and privacy.": "Частые вопросы о Descall: аккаунты, приложение для ПК, звонки, демонстрация экрана и конфиденциальность.",
  "Friend": "Друг",
  "Friend Request": "Запрос в друзья",
  "Friend Request Notifications": "Уведомления о запросах в друзья",
  "Friend Requests": "Запросы в друзья",
  "Friend action failed.": "Не удалось выполнить действие с другом.",
  "Friend groups": "Компании друзей",
  "Friend groups often pay for Nitro out of habit. Core voice and screen share should not require a subscription, that’s the promise of a free Discord alternative like Descall.": "Компании друзей часто платят за Nitro по привычке. Основной голос и демонстрация экрана не должны требовать подписки — в этом и смысл бесплатной альтернативы Discord, такой как Descall.",
  "Friend groups outgrow Discord chrome": "Компаниям друзей тесно в интерфейсе Discord",
  "Friend groups, gaming squads, and small-to-mid communities that need servers, roles, voice, and screen share often prefer Descall as a lighter Discord alternative. Keep Discord if you still rely on huge bot ecosystems.": "Компании друзей, игровые команды и сообщества малого и среднего размера, которым нужны серверы, роли, голос и демонстрация экрана, часто выбирают Descall как более лёгкую альтернативу Discord. Оставайтесь в Discord, если всё ещё зависите от огромной экосистемы ботов.",
  "Friend invite": "Приглашение в друзья",
  "Friend list, online status, and invites, jump from DMs into a server voice channel in one flow.": "Список друзей, статус в сети и приглашения — из ЛС прямо в голосовой канал сервера.",
  "Friend online notifications": "Уведомления о друзьях в сети",
  "Friend presence, activity status, and quick voice with your squad.": "Статус друзей, активность и быстрый голосовой чат с командой.",
  "Friend request accepted": "Запрос в друзья принят",
  "Friend requests, blocking, and presence/status": "Запросы в друзья, блокировка и статус в сети",
  "Friend requests, online presence, and quick invites so your squad can jump into chat or voice.": "Запросы в друзья, статус в сети и быстрые приглашения, чтобы команда могла сразу зайти в чат или голосовой.",
  "Friend voice + servers → Descall. Huge community → Discord. Pure voice server → TeamSpeak. Read our compare page before you force a full migration.": "Голос с друзьями + серверы → Descall. Огромное сообщество → Discord. Чисто голосовой сервер → TeamSpeak. Прежде чем устраивать полный переезд, почитайте нашу страницу сравнения.",
  "Friend-group chat and voice without Nitro friction": "Чат и голос для компании друзей без ограничений Nitro",
  "Friends": "Друзья",
  "Friends & presence": "Друзья и статус",
  "Friends Only": "Только друзья",
  "Friends and presence": "Друзья и статус",
  "Friends and presence inside Descall": "Друзья и статусы прямо в Descall",
  "Friends can see your activity": "Друзья видят вашу активность",
  "Friends hangout": "Тусовка друзей",
  "Friends list, ready for a lobby or a call": "Список друзей — готов к лобби или звонку",
  "Friends usually want three things: who’s online, a place to chat, and a fast call button. Descall focuses on that private community loop, without forcing you to administer roles for a five-person squad.": "Друзьям обычно нужны три вещи: видеть, кто в сети, место для переписки и быстрая кнопка звонка. Descall делает упор именно на этот приватный круг общения и не заставляет настраивать роли для команды из пяти человек.",
  "Friends · DMs · Groups": "Друзья · ЛС · Группы",
  "Friends' active sessions will appear here": "Здесь появятся активные сеансы друзей",
  "Friends, presence & status": "Друзья, присутствие и статус",
