  "How to move a friend group from Discord Nitro habits to a free Discord alternative with servers, voice, video, and screen share.": "Как отучить компанию друзей от Discord Nitro и перейти на бесплатную альтернативу с серверами, голосом, видео и демонстрацией экрана.",
