  "Huge public servers and bot ecosystems can stay on Discord. Friend groups and squads that wanted a lighter Discord alternative usually finish the move in under a week.": "Огромные публичные серверы и экосистемы ботов могут остаться в Discord. Компании друзей и команды, которым нужна более лёгкая альтернатива, обычно переезжают меньше чем за неделю.",
