  "If audio/video quality or anything else was off, tell us. 30 seconds is enough.": "Если со звуком, видео или чем-то ещё были проблемы, расскажите нам. Хватит 30 секунд.",
  "If you do not need a bot store, Descall is a lighter app like Discord for DMs, servers, and calls.": "Если вам не нужен магазин ботов, Descall — более лёгкое приложение как Discord для ЛС, серверов и звонков.",
  "If you need bots, Stages, and mega-servers, Discord remains the default. Many groups dual-stack: Discord for public, Descall for private voice.": "Если вам нужны боты, трибуны и мегасерверы, Discord остаётся стандартом. Многие группы пользуются обоими: Discord для публичного, Descall для приватного голосового.",
  "If you want chat, servers with voice lobbies, and screen share without Nitro, Descall is a strong Discord alternative for gaming friend groups.": "Если вам нужны чат, серверы с голосовыми лобби и демонстрация экрана без Nitro, Descall — сильная альтернатива Discord для игровых компаний друзей.",
  "If you win": "При выигрыше",
  "If your “community” is your friends list, Descall is a better daily driver than a Discord alternative pretending to be a public square. Keep Discord for big servers; keep Descall for the group chat that actually rings.": "Если ваше «сообщество» — это список друзей, Descall лучше подходит на каждый день, чем альтернатива Discord, изображающая городскую площадь. Оставьте Discord для больших серверов, а Descall — для группового чата, где действительно звонят.",
