  "Install the Descall desktop app to share game and app activity automatically.": "Установите настольное приложение Descall, чтобы автоматически показывать активность в играх и приложениях.",
  "Install the Windows client for desktop gaming, use Android or the web app when you’re away from the PC. We don’t claim every platform Discord covers, we claim the ones Descall ships today.": "Установите клиент для Windows для игр на ПК, а вдали от компьютера используйте Android или веб-версию. Мы не заявляем все платформы, что есть у Discord, — только те, на которых Descall работает уже сегодня.",
