  "Look for free WebRTC calls, screen share, and a desktop app. Descall is built for that without paywalling talk time.": "Ищите бесплатные звонки на WebRTC, демонстрацию экрана и приложение для ПК. Descall создан именно для этого и не берёт плату за время общения.",
