  "More about Descall": "Подробнее о Descall",
  "More options": "Другие действия",
  "More reactions": "Другие реакции",
  "Most Discord replacement attempts fail when voice feels worse. Descall invests in WebRTC calls, TURN, and screen-share presets so nightly voice stays easy.": "Большинство попыток заменить Discord проваливаются, когда голос звучит хуже. Descall вкладывается в звонки на WebRTC, TURN и пресеты демонстрации экрана, чтобы вечерние созвоны оставались простыми.",
  "Most community platforms either drown you in mega-server chrome or skip structure entirely. Descall gives you real servers with categories, text/voice/stage channels, roles, channel overrides, and ready-made community templates, so a clan, class, or creator circle can launch organized in minutes.": "Большинство платформ для сообществ либо топят вас в интерфейсе мегасерверов, либо вообще обходятся без структуры. Descall даёт настоящие серверы с категориями, текстовыми, голосовыми и трибунными каналами, ролями, переопределениями каналов и готовыми шаблонами сообществ — клан, класс или круг автора запустятся организованно за считаные минуты.",
  "Most friend groups feel settled within two weeks of moving evening voice.": "Большинство компаний друзей привыкают в течение двух недель после переноса вечерних созвонов.",
  "Most groups dual-stack for a month, then realize 90% of pings happen on Descall. That’s a healthy Discord replacement path, no big-bang migration required.": "Большинство групп месяц пользуются обоими приложениями, а потом понимают, что 90% пингов приходится на Descall. Это здоровый путь замены Discord — без резкого переезда.",
  "Most groups want both. Descall pairs DMs and servers with the same voice stack so you are not juggling two apps.": "Большинству групп нужно и то и другое. В Descall ЛС и серверы работают на одном голосовом движке, так что не нужно разрываться между двумя приложениями.",
  "Most worn on Descall": "Самые популярные в Descall",
