  "Personalize your Descall interface": "Настройте интерфейс Descall под себя",
  "Photo": "Фото",
  "Photos": "Фото",
  "PiP / minimize-friendly call UX": "Интерфейс звонка с PiP и удобным сворачиванием",
  "Pick Descall for nightly friend voice and servers without Nitro. Keep Discord if you still depend on a large bot marketplace or huge public servers.": "Выбирайте Descall для вечерних созвонов с друзьями и серверов без Nitro. Оставайтесь в Discord, если всё ещё зависите от большого магазина ботов или огромных публичных серверов.",
  "Pick Descall when your group wants a lighter Discord alternative for chat, voice, and screen share. Keep Discord when you still run large public communities and bots.": "Выбирайте Descall, если вашей группе нужна более лёгкая альтернатива Discord для чата, голоса и демонстрации экрана. Оставайтесь в Discord, если всё ещё ведёте большие публичные сообщества с ботами.",
  "Pick Gaming, Friends, or Community templates so roles and staff rooms appear ready. Invite codes replace Discord’s invite links.": "Выберите шаблон «Игры», «Друзья» или «Сообщество» — роли и комнаты для персонала появятся сразу. Коды приглашений заменяют ссылки-приглашения Discord.",
  "Pick a DM or group, then start a voice or video call": "Выберите ЛС или группу, затем начните голосовой звонок или видеозвонок",
  "Pick a GIF": "Выберите GIF",
  "Pick a friend, start a DM, or create a group, Descall keeps it light.": "Выберите друга, напишите в ЛС или создайте группу — в Descall всё просто.",
  "Pick a home": "Выберите раздел",
  "Pick a photo, then zoom and crop. JPG, PNG, WebP or GIF · Max 8 MB": "Выберите фото, затем увеличьте и обрежьте. JPG, PNG, WebP или GIF · до 8 МБ",
  "Pick a role to see and manage its members.": "Выберите роль, чтобы увидеть её участников и управлять ими.",
  "Pick a server on the left, or create a new one with +.": "Выберите сервер слева или создайте новый кнопкой +.",
  "Pick a template": "Выберите шаблон",
  "Pick a template (friends, gaming) or start empty. Roles and channels ship ready.": "Выберите шаблон (для друзей, для игр) или начните с пустого сервера. Роли и каналы уже готовы.",
  "Pick a template or start from scratch.": "Выберите шаблон или начните с нуля.",
