  "Start a voice or video call from Quick dial, a chat, or a group.": "Начните голосовой звонок или видеозвонок из быстрого вызова, чата или группы.",
  "Start free": "Начать бесплатно",
  "Start from a template or an empty server. Templates include text channels, voice channels, and roles such as Admin, Moderator, and Member.": "Начните с шаблона или пустого сервера. Шаблоны включают текстовые и голосовые каналы, а также роли, например «Админ», «Модератор» и «Участник».",
  "Start from scratch": "Начать с нуля",
  "Start from scratch or pick a template packed with roles, text & voice channels, topics, slowmode, and staff permission overrides, gaming, community, study, friends, or streaming.": "Начните с нуля или выберите шаблон с ролями, текстовыми и голосовыми каналами, темами, медленным режимом и переопределениями прав персонала: игры, сообщество, учёба, друзья или стриминг.",
