  "Start with /alternatives and /compare/discord, or read the Discord competitors blog post.": "Начните с /alternatives и /compare/discord или прочитайте статью в блоге о конкурентах Discord.",
  "Start with your real job-to-be-done: friend DMs, group voice, screen share, or a gaming server. If you need mega-servers and bot ecosystems, Discord still leads. If you want a lighter Discord alternative that keeps communication free, Descall is built for you.": "Начните с того, что вам действительно нужно: ЛС с друзьями, групповой голос, демонстрация экрана или игровой сервер. Если нужны мегасерверы и экосистема ботов, Discord по-прежнему впереди. Если хотите более лёгкую альтернативу Discord, где общение остаётся бесплатным, Descall создан для вас.",
