  "Text, voice, and stage channels with categories, Discord-style structure, lighter feel": "Текстовые, голосовые и трибунные каналы с категориями: структура как в Discord, но легче",
  "Text, voice, and stage channels with categories, a lighter home for real communities": "Текстовые, голосовые и трибунные каналы с категориями — более лёгкий дом для настоящих сообществ",
  "Thank You!": "Спасибо!",
