  "The app downloads new versions in the background": "Приложение скачивает новые версии в фоне",
  "The best free Discord alternative for friends & gamers": "Лучшая бесплатная альтернатива Discord для друзей и геймеров",
  "The best platforms like Discord aren’t pixel clones, they remove the parts of Discord your group never used.": "Лучшие платформы как Discord — не попиксельные клоны: они убирают из Discord то, чем ваша группа никогда не пользовалась.",
  "The call was answered on another device.": "На звонок ответили на другом устройстве.",
  "The call was declined on another device.": "Звонок отклонён на другом устройстве.",
  "The connection is slow. Saved data is still here. Retrying.": "Соединение медленное. Сохранённые данные на месте. Повторяем попытку.",
  "The download and the website show the same servers and chats": "В приложении и на сайте одни и те же серверы и чаты",
  "The group will show its initials again for everyone.": "У группы снова будут показываться инициалы для всех.",
  "The page ran into a problem. You can try again, or go back home.": "На странице возникла проблема. Попробуйте ещё раз или вернитесь на главную.",
  "The quick brown fox jumps over the lazy dog": "Съешь же ещё этих мягких французских булок да выпей чаю",
  "The quick brown fox jumps over the lazy dog.": "Съешь же ещё этих мягких французских булок да выпей чаю.",
  "The saved microphone was not found, using the default microphone.": "Сохранённый микрофон не найден, используется микрофон по умолчанию.",
  "The selected microphone was not found.": "Выбранный микрофон не найден.",
  "The server did not answer in time. Check your connection and try again.": "Сервер не ответил вовремя. Проверьте подключение и попробуйте ещё раз.",
  "The short answer": "Коротко",
  "The ultimate chat application for your desktop. Fast, secure, and beautifully designed.": "Лучшее приложение для общения на компьютере. Быстрое, безопасное и красивое.",
  "Their call": "Выбор соперника",
  "Their microphone is connecting…": "Микрофон собеседника подключается…",
  "Theme": "Тема",
  "Theme & look": "Тема и внешний вид",
  "Themes": "Темы",
  "Themes, frames, and effects via DesCoin. Core chat, servers, and calls stay free forever.": "Темы, рамки и эффекты за DesCoin. Основной чат, серверы и звонки навсегда остаются бесплатными.",
  "Then enable notifications for calls and DMs.": "Затем включите уведомления о звонках и личных сообщениях.",
  "There is no bulk Discord history importer today. Pin key links, rebuild channels, and start fresh voice nights on Descall.": "Сейчас нет массового импорта истории из Discord. Закрепите важные ссылки, воссоздайте каналы и начните новые голосовые вечера в Descall.",
  "They answered on a locked iPhone but couldn't join in time. Try calling again.": "Собеседник ответил на заблокированном iPhone, но не успел подключиться. Попробуйте позвонить ещё раз.",
  "This account doesn’t have an email address, so we can’t send a reset code. Contact support and we’ll help you recover access.": "У этого аккаунта нет адреса электронной почты, поэтому мы не можем отправить код для сброса. Обратитесь в поддержку, и мы поможем восстановить доступ.",
  "This account has no email on file. Contact support@descall.com to recover access.": "У этого аккаунта не указан e-mail. Чтобы восстановить доступ, напишите на support@descall.com.",
  "This account is closed because the account holder is under 13. Account deletion has started.": "Этот аккаунт закрыт, так как его владельцу меньше 13 лет. Удаление аккаунта начато.",
  "This account's username is tied to admin access and can't be changed.": "Имя пользователя этого аккаунта связано с правами администратора, и его нельзя изменить.",
  "This action cannot be undone.": "Это действие нельзя отменить.",
  "This chat leaves your list. Messages stay, it comes back if they write you.": "Этот чат исчезнет из списка. Сообщения сохранятся, а чат вернётся, если вам напишут.",
  "This device": "Это устройство",
  "This device can't create an account right now. Try again later.": "С этого устройства сейчас нельзя создать аккаунт. Попробуйте позже.",
  "This device can’t share system/tab audio with screen share.": "Это устройство не может передавать системный звук или звук вкладки при демонстрации экрана. В мобильных браузерах звук YouTube и приложений обычно нельзя захватить при демонстрации экрана — только видео.",
  "This error has been logged. Please contact support if it persists.": "Ошибка записана в журнал. Если она повторяется, обратитесь в поддержку.",
