  "Windows users should install the desktop client for fewer browser tab mishaps. Android and web cover the rest of the group.": "Пользователям Windows лучше установить приложение для ПК, чтобы меньше путаться во вкладках браузера. Остальная группа может пользоваться Android и веб-версией.",
  "Won": "Выигрыш",
  "Work-first chat. Huddles exist, but gamers looking for a Discord alternative usually want evenings, not tickets.": "Чат в первую очередь для работы. Хаддлы есть, но геймерам, которые ищут альтернативу Discord, обычно нужны вечера, а не тикеты.",
