  "You can update profile settings, leave groups, and request account deletion via Contact. For questions about this policy, use the Contact page.": "Вы можете изменять настройки профиля, выходить из групп и запрашивать удаление аккаунта через страницу «Контакты». С вопросами об этой политике также обращайтесь через страницу «Контакты».",
